/*
 * @lc app=leetcode id=3321 lang=java
 *
 * [3321] Find X-Sum of All K-Long Subarrays II
 */
fun findXSum(nums: IntArray, k: Int, x: Int): LongArray = HashMap<Int, Int>().let { cnt -> java.util.TreeSet<Pair<Int, Int>>(compareByDescending<Pair<Int, Int>> { it.first }.thenByDescending { it.second }).let { top -> java.util.TreeSet<Pair<Int, Int>>(compareByDescending<Pair<Int, Int>> { it.first }.thenByDescending { it.second }).let { rest -> LongArray(1).let { sum -> fun upd(v: Int, delta: Int) = cnt[v]?.let { f -> if (top.remove(f to v)) sum[0] -= f.toLong() * v else rest.remove(f to v) }.let { (cnt.getOrDefault(v, 0) + delta).let { nf -> if (nf > 0) cnt[v] = nf.also { rest.add(nf to v) } else cnt.remove(v) } }.also { while (top.size < x && rest.isNotEmpty()) rest.pollFirst()!!.let { top.add(it).also { sum[0] += it.first.toLong() * it.second } } }.also { while (top.isNotEmpty() && rest.isNotEmpty() && (top.last().first < rest.first().first || (top.last().first == rest.first().first && top.last().second < rest.first().second))) { top.pollLast()!!.let { t -> rest.pollFirst()!!.let { r -> sum[0] -= t.first.toLong() * t.second.also { top.add(r).also { sum[0] += r.first.toLong() * r.second.also { rest.add(t) } } } } } } } }.let { LongArray(nums.size - k + 1).also { ans -> (0 until nums.size).forEach { i -> upd(nums[i], 1).also { if (i >= k) upd(nums[i - k], -1) }.also { if (i >= k - 1) ans[i - k + 1] = sum[0] } } } } } } } }